/**
 * `withPostman(config)` — config-level wrapper for Playwright.
 *
 * Returns a new Playwright config with:
 *  - Playwright's built-in `json` reporter appended (writing to
 *    `test-results/playwright-report.json`, i.e. inside Playwright's own
 *    default `outputDir`) when no `json` reporter is already configured. The
 *    Postman CLI reads the resulting report plus the per-test `trace.zip`
 *    files Playwright writes under the same `outputDir` directly.
 *  - `use.trace` ensured to satisfy the Postman capture requirements:
 *    `mode === 'on'` AND `snapshots !== false`. The HAR/network tracer
 *    Postman parses is gated on both. We only enforce these two fields —
 *    other trace options the user sets (screenshots, sources, attachments,
 *    etc.) are intentionally left alone; that is on the user.
 *
 * Behaviour:
 *  - If the input config does not configure `use.trace`, it is set to
 *    `{ mode: 'on', snapshots: true }`.
 *  - If the input config configures a compatible `use.trace` (the string
 *    `'on'`, or an object with `mode === 'on'` and `snapshots !== false`),
 *    it is preserved as-is.
 *  - Anything else throws — silently overriding the user's intent (e.g.
 *    `'off'`, `'on-first-retry'`, `{ snapshots: false }`) would leave them
 *    with empty captures.
 *
 * Never mutates the input config; preserves any user-defined reporters and
 * other `use.*` fields. Does not touch Playwright's own `outputDir`.
 */
export declare function withPostman<T extends Record<string, any>>(config: T): T;
